// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SubscriptionQuotaDebtAdjustment) predicate.SubscriptionQuotaDebtAdjustment {
	return predicate.SubscriptionQuotaDebtAdjustment(sql.AndPredicates(predicates...))
}

